F4={'TL':None,'TR':'M','C':'S','BL':'dot','BR':None}
# figures alternate diagonals; from a TR/BL figure: BL->TL, TR->centre, new symbol at BR
F5={'TL':F4['BL'],'C':F4['TR'],'BR':'new'}
used={'star','arrow','sq','S','M','dot'}
opts={'A':{'TR':'dot','C':'M','BL':'S'},'B':{'TL':'dot','C':'M','BR':'T'},'C':{'TL':'dot','C':'M','BR':'S'},'D':{'TR':'dot','C':'M','BL':'T'}}
def fits(o):
    return set(o)=={'TL','C','BR'} and o['TL']==F5['TL'] and o['C']==F5['C'] and o['BR'] not in used
res=[k for k in opts if fits(opts[k])]
assert res==['B'],res

# quarter = bottom-left after folding top->bottom and right->left; cuts: E near left edge (just below middle), reversed-E near bottom centre
cuts=[('E',('left','below-mid')),('R',('centre-left','bottom'))]
flip={'E':'R','R':'E'}
res=set()
for s,(x,y) in cuts:
    for mx in (False,True):
        for my in (False,True):
            xx={'left':'right','centre-left':'centre-right'}[x] if mx else x
            yy={'below-mid':'above-mid','bottom':'top'}[y] if my else y
            ss=flip[s] if mx else s   # E is symmetric top-bottom
            res.add((ss,xx,yy))
B={('E','left','below-mid'),('E','left','above-mid'),('R','right','below-mid'),('R','right','above-mid'),
   ('R','centre-left','bottom'),('E','centre-right','bottom'),('R','centre-left','top'),('E','centre-right','top')}
counts={'A':4,'B':8,'C':4,'D':6}
assert res==B and len(res)==counts['B']
for k in 'ACD': assert counts[k]!=len(res)
